//! AssumeUTXO trust anchor.
//!
//! These constants commit to a specific UTXO set snapshot. They are the
//! out-of-band trust input that lets us bootstrap a pruned node without
//! validating the chain from genesis. The download source is untrusted —
//! the file is verified against `ASSUMEUTXO_HASH` after download.
//!
//! Generated by `convert_snapshot` from a Bitcoin Core `dumptxoutset` taken
//! at block 943,500. Regenerated after the converter's uncompressed-P2PK
//! fix (Core compressed-script types 0x04/0x05 now decode to the 67-byte
//! `41 04 <x> <y> ac` script); the earlier hash
//! 705528fe…2d133e committed to 35-byte compressed-key scripts for those
//! coins and must never be accepted again.

/// Block height at which the snapshot was taken.
pub const ASSUMEUTXO_HEIGHT: u32 = 943_500;

/// SHA256 hash of the HUTX-format UTXO set, computed by `UtxoSet::compute_hash`.
/// Verified against the file's stored hash on load, then recomputed during
/// insertion to detect tampering of the body (the entries).
///
/// This hash does NOT cover the HUTX header's `height` / `block_hash`
/// fields (format v1). Those are authenticated separately by requiring them
/// to equal `ASSUMEUTXO_HEIGHT` / `ASSUMEUTXO_BLOCK_HASH` (see
/// `SnapshotAnchor` and `UtxoSet::load_snapshot`). A v2 format that folds
/// the header into the hashed preimage is left to ticket 032.
pub const ASSUMEUTXO_HASH: [u8; 32] = [
    0xa6, 0x5f, 0xdd, 0x39, 0x10, 0x1c, 0x64, 0xf0,
    0x0d, 0x6c, 0x5c, 0xef, 0xb1, 0x34, 0x08, 0x0e,
    0xc9, 0x50, 0x06, 0xc3, 0x4b, 0xd6, 0xc2, 0x5f,
    0x29, 0x64, 0x77, 0x30, 0xae, 0x1b, 0xf7, 0x34,
];

/// Snapshot content hashes that were once shipped and later found to be
/// wrong. A UTXO set loaded from one of them is discarded on open (see
/// `UtxoSet::open`) so the app re-imports the current snapshot.
///
/// - `705528fe…2d133e`: 943,500 file built before the converter decoded
///   Core's compressed-script types 0x04/0x05 as uncompressed P2PK; 34,336
///   coins carried a 35-byte compressed-key script instead of the real
///   67-byte one, so blocks spending them would fail validation.
pub const RETRACTED_SNAPSHOT_HASHES: &[[u8; 32]] = &[[
    0x70, 0x55, 0x28, 0xfe, 0x00, 0x33, 0x29, 0xe0,
    0xe6, 0xde, 0x5c, 0x85, 0x4b, 0x83, 0xd5, 0x7b,
    0x0b, 0xad, 0xc2, 0xb9, 0x5b, 0x60, 0xdc, 0x73,
    0xa7, 0xa4, 0x0f, 0x22, 0xf6, 0x2d, 0x13, 0x3e,
]];

/// Exact number of UTXOs in the snapshot (the HUTX header's `count`, equal
/// to Core's `dumptxoutset` coin count / `gettxoutsetinfo txouts`).
///
/// For cross-checking against Core: the MuHash3072 Hercules computes over
/// this file (what `load_snapshot` stores and TrustInfo shows), in Core's
/// `gettxoutsetinfo muhash 943500` display order, is
/// 73877c075918cdf010b181b7cedb99715df424f70d52d412b0c8d78175d2de4c
/// (not yet compared with a Core node).
pub const ASSUMEUTXO_UTXO_COUNT: u64 = 165_208_261;

/// Block hash at the snapshot height (internal byte order, NOT display order).
/// Display order: 00000000000000000001fad98be927b937e32494834f109166fa2ae2e1d1b91a
pub const ASSUMEUTXO_BLOCK_HASH: [u8; 32] = [
    0x1a, 0xb9, 0xd1, 0xe1, 0xe2, 0x2a, 0xfa, 0x66,
    0x91, 0x10, 0x4f, 0x83, 0x94, 0x24, 0xe3, 0x37,
    0xb9, 0x27, 0xe9, 0x8b, 0xd9, 0xfa, 0x01, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
];

/// Minimum cumulative chainwork a header chain must have before we trust it
/// enough to validate blocks against it or activate a snapshot (the
/// equivalent of Bitcoin Core's `nMinimumChainWork`). 256-bit little-endian,
/// same representation as `validation::chainwork_for_headers`.
///
/// Derived from the anchor, not invented: this is the mainnet chainwork at
/// `ASSUMEUTXO_HEIGHT` (943,500), i.e. Core's `getblockheader <anchor>`
/// `chainwork` field. Computed by summing `work(bits)` over every header
/// 0..=943,500 (bits taken from each 2016-block epoch). The same computation
/// at height 938,343 reproduces Bitcoin Core v31.1's mainnet
/// `nMinimumChainWork` (0x...01128750f82f4c366153a3a030, `chainparams.cpp`,
/// tag v31.1 / bfa6a4b79cd4c1562fd32857e3147763efae37fb) exactly.
///
/// Must be regenerated whenever the anchor constants above are bumped.
/// Display order (Core): 00000000000000000000000000000000000000011c9554a693f4170c17ba9148
pub const MIN_CHAIN_WORK: [u8; 32] = [
    0x48, 0x91, 0xba, 0x17, 0x0c, 0x17, 0xf4, 0x93,
    0xa6, 0x54, 0x95, 0x1c, 0x01, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
];

/// What a snapshot file must commit to before we load it: the header's
/// `height` and `block_hash`, the exact number of entries, plus the content
/// hash of those entries.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SnapshotAnchor {
    pub height: u32,
    /// Internal byte order, same as `ASSUMEUTXO_BLOCK_HASH`.
    pub block_hash: [u8; 32],
    pub utxo_hash: [u8; 32],
    /// Exact entry count the header must announce. Checked before the
    /// header's count is used to size the LMDB map, so a file can't make
    /// us grow (or fail to grow) the map based on an unauthenticated number.
    pub utxo_count: u64,
}

/// The anchor compiled into this release.
pub const MAINNET_ANCHOR: SnapshotAnchor = SnapshotAnchor {
    height: ASSUMEUTXO_HEIGHT,
    block_hash: ASSUMEUTXO_BLOCK_HASH,
    utxo_hash: ASSUMEUTXO_HASH,
    utxo_count: ASSUMEUTXO_UTXO_COUNT,
};

/// Public download URL for the gzip-compressed HUTX snapshot.
/// Hosted on Cloudflare R2 (zero egress fees, edge-cached).
pub const SNAPSHOT_DOWNLOAD_URL: &str =
    "https://pub-341db11a2808417d91d4fcabc62a2260.r2.dev/hercules-943500-utxo-v2.hutx.gz";

/// Approximate compressed download size in bytes (for UI progress estimates).
pub const SNAPSHOT_DOWNLOAD_SIZE: u64 = 8_781_448_895;

/// LMDB map the AssumeUTXO set needs once imported: the env is ~12 GB at
/// this anchor, plus headroom for block validation in the same session.
/// Checked before the download starts (ticket 030) so a device whose
/// address space can't hold the map fails fast instead of after ~9 GB.
/// Bump with the anchor if the set grows.
pub const SNAPSHOT_MAP_REQUIRED_BYTES: u64 = 16 << 30;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn block_hash_matches_display() {
        let display = "00000000000000000001fad98be927b937e32494834f109166fa2ae2e1d1b91a";
        let mut from_display = hex::decode(display).unwrap();
        from_display.reverse();
        assert_eq!(&from_display[..], &ASSUMEUTXO_BLOCK_HASH[..]);
    }

    #[test]
    fn utxo_hash_matches_display() {
        let display = "a65fdd39101c64f00d6c5cefb134080ec95006c34bd6c25f29647730ae1bf734";
        let from_display = hex::decode(display).unwrap();
        assert_eq!(&from_display[..], &ASSUMEUTXO_HASH[..]);
    }

    #[test]
    fn current_hash_is_not_retracted() {
        assert!(!RETRACTED_SNAPSHOT_HASHES.contains(&ASSUMEUTXO_HASH));
        assert_eq!(
            hex::encode(RETRACTED_SNAPSHOT_HASHES[0]),
            "705528fe003329e0e6de5c854b83d57b0badc2b95b60dc73a7a40f22f62d133e"
        );
    }

    #[test]
    fn min_chain_work_matches_display() {
        let display = "00000000000000000000000000000000000000011c9554a693f4170c17ba9148";
        let mut from_display = hex::decode(display).unwrap();
        from_display.reverse();
        assert_eq!(&from_display[..], &MIN_CHAIN_WORK[..]);
    }

    #[test]
    fn min_chain_work_exceeds_core_v31_1_floor() {
        // Core v31.1 mainnet nMinimumChainWork (block 938,343). Our anchor
        // is higher, so our floor must be strictly above Core's.
        let core = "0000000000000000000000000000000000000001128750f82f4c366153a3a030";
        let mut core_le = [0u8; 32];
        core_le.copy_from_slice(&hex::decode(core).unwrap());
        core_le.reverse();
        assert!(crate::validation::u256_gt(&MIN_CHAIN_WORK, &core_le));
    }
}
